// Every navigational state lives in the URL, so Back, reload and shared links
// return to the same view, selection and reading position.

import site from "@instance/site";
import { useEffect, useSyncExternalStore } from "react";
import type { Stage } from "../api/types";
import { arrive, leaveAs, pushEntry, replaceEntry, setDefaultLabel } from "./trail";
import { LIBRARY, libraryHref, movedLibraryPath, parseLibraryPath, pdfParams } from "./libraryAddress";

export type Trace = "rests" | "uses";

export type Route =
  | { view: "home"; anchor?: string }
  | {
      view: "map";
      node?: string;
      trace?: Trace;
      lens?: Stage;
      goal?: string;
      /** A selected step between two records: an `ArgEdge.key`. */
      edge?: string;
      /** The Lean graph of this argument in place of the argument. */
      lean?: boolean;
      /** The Lean declaration open in the sheet, with its module where a name is declared twice. */
      decl?: string;
      declModule?: string;
    }
  | {
      view: "read";
      stage: Stage;
      anchor?: string;
      /** The exact source to land on: a line ("120"), lines ("120-134") or a byte range ("b4521-5120"). */
      at?: string;
      /** The right pane shows the Lean view. */
      lean?: boolean;
      /** The reader chose the graph: a statement or declaration opened here stays on the graph. */
      graph?: boolean;
      node?: string;
      beside?: { stage: Stage; anchor: string };
      /** The Lean declaration open beside the paper, with its module where a name is declared twice. */
      decl?: string;
      declModule?: string;
      /** The authors' PDF in place of the typeset text (`view=pdf`), opened at this page. */
      pdf?: boolean;
      page?: number;
      /** A retired phrase link (`/@<id>` of a library paper): the paper opens with a notice, at no phrase. */
      retired?: string;
      /** A phrase address (`/@<id>`) that names no phrase of the paper: it opens at the top with a notice saying so. */
      missing?: string;
    }
  | { view: "checks"; node?: string }
  | {
      view: "compare";
      /** The record read across its levels. Without one, the table of every step. */
      node?: string;
      /** The table, opened at this record. */
      at?: string;
      /** Which levels show, in order, when the reader has chosen. */
      levels?: Level[];
      /** The table with the steps only some of the levels have, as well as those all of them have. */
      any?: boolean;
    }
  | {
      view: "lean";
      module?: string;
      decl?: string;
      /** The module's whole source, with these lines lit ("35-59"), or "all". */
      file?: string;
      /** A folder of the tree, as its path. */
      folder?: string;
      /** The list of declarations linked to the papers. */
      index?: "papers";
    }
  | { view: "about"; anchor?: string }
  | {
      view: "search";
      /** The exact words typed, as given. */
      q: string;
      /** Which kind of result to list; absent means the first kind with matches. */
      type?: SearchType;
      /** 1-based page of results within that kind. */
      page?: number;
    }
  | { view: "missing"; path: string };

/** The levels of the funnel, from the Lean down to the exposition. */
export const LEVELS = ["lean", "long", "short", "expository"] as const;
export type Level = (typeof LEVELS)[number];

function isLevel(value: string): value is Level {
  return (LEVELS as readonly string[]).includes(value);
}

/** The kinds of result search lists, each one table of the edition. */
export const SEARCH_TYPES = ["records", "statements", "sections", "text", "passages", "citations", "sources", "checks"] as const;
export type SearchType = (typeof SEARCH_TYPES)[number];

function isSearchType(value: string | null): value is SearchType {
  return !!value && (SEARCH_TYPES as readonly string[]).includes(value);
}

// The three accounts, and a library paper's companion documents, each read at /read/<page>/.
const STAGE_SET = new Set(["long", "short", "expository", ...(site.library?.companions ?? []).map((c) => c.slot)]);
const BASE = (import.meta.env.BASE_URL ?? "/").replace(/\/$/, "");

function isStage(value: string | null | undefined): value is Stage {
  return !!value && STAGE_SET.has(value);
}

function fragmentOf(url: URL): string | undefined {
  const raw = url.hash.replace(/^#/, "");
  if (!raw) return undefined;
  try {
    return decodeURIComponent(raw);
  } catch {
    // A malformed fragment should reach the reader's missing-anchor notice,
    // rather than preventing the whole application from opening.
    return raw;
  }
}

const AT_PARAM = /^(?:\d+(?:-\d+)?|b\d+-\d+)$/;

export function parseRoute(url: URL): Route {
  let path = url.pathname;
  if (BASE && path.startsWith(BASE)) path = path.slice(BASE.length) || "/";
  path = path.replace(/\/+$/, "") || "/";
  const q = url.searchParams;
  const hash = fragmentOf(url);
  // The front page lives at "/". The map moved to "/map"; a link to "/" that
  // carries any map parameter was made when the map lived there, so it still
  // opens the map.
  const library = parseLibraryPath(path, q, hash);
  if (library) return library;
  const MAP_PARAMS = ["g", "n", "t", "lens", "e"];
  if (path === "/" && !MAP_PARAMS.some((name) => q.has(name))) return hash ? { view: "home", anchor: hash } : { view: "home" };
  if (path === "/" || path === "/map") {
    const trace = q.get("t");
    const lens = q.get("lens");
    return {
      view: "map",
      node: q.get("n") ?? undefined,
      trace: trace === "rests" || trace === "uses" ? trace : undefined,
      lens: isStage(lens) ? lens : undefined,
      goal: q.get("g") ?? undefined,
      edge: edgeKeyFromParam(q.get("e")),
      lean: q.get("v") === "lean" || undefined,
      decl: q.get("d") ?? undefined,
      declModule: q.get("dm") ?? undefined,
    };
  }
  const read = path.match(/^\/read\/([a-z0-9-]+)$/);
  if (read && isStage(read[1])) {
    const beside = q.get("beside");
    const [bStage, ...bAnchor] = beside ? beside.split(":") : [];
    return {
      view: "read",
      stage: read[1],
      anchor: hash,
      at: AT_PARAM.test(q.get("l") ?? "") ? q.get("l")! : undefined,
      lean: q.get("v") === "lean" || undefined,
      graph: q.get("v") === "graph" || undefined,
      node: q.get("n") ?? undefined,
      beside: isStage(bStage) && bAnchor.length ? { stage: bStage, anchor: bAnchor.join(":") } : undefined,
      decl: q.get("d") ?? undefined,
      declModule: q.get("dm") ?? undefined,
      ...pdfParams(q),
    };
  }
  if (path === "/checks") return { view: "checks", node: q.get("n") ?? undefined };
  if (path === "/compare") {
    const levels = q.get("levels")?.split(",").filter(isLevel);
    return { view: "compare", node: q.get("n") ?? undefined, at: q.get("at") ?? undefined, levels: levels?.length ? levels : undefined, any: q.get("in") === "any" || undefined };
  }
  if (path === "/lean") return { view: "lean", module: q.get("m") ?? undefined, decl: q.get("d") ?? undefined, file: q.get("file") ?? undefined, folder: q.get("f") ?? undefined, index: q.get("list") === "papers" ? "papers" : undefined };
  if (path === "/about") return { view: "about", anchor: hash };
  if (path === "/search") {
    const type = q.get("type");
    const page = Number(q.get("p"));
    return {
      view: "search",
      q: q.get("q") ?? "",
      type: isSearchType(type) ? type : undefined,
      page: Number.isInteger(page) && page > 1 ? page : undefined,
    };
  }
  return { view: "missing", path };
}

// Edges travel as `from~to~kind`; the key itself uses arrows, which read badly in a URL.
function edgeKeyFromParam(value: string | null): string | undefined {
  const parts = value?.split("~") ?? [];
  return parts.length === 3 && parts.every(Boolean) ? parts.join("→") : undefined;
}

function edgeParam(key: string): string {
  return key.split("→").join("~");
}

/** Like URLSearchParams, but keeps `:` and `,` readable; both are legal in a query. */
class Query {
  private pairs: [string, string][] = [];
  set(name: string, value: string): void {
    this.pairs.push([name, value]);
  }
  toString(): string {
    const encode = (v: string) => encodeURIComponent(v).replace(/%3A/gi, ":").replace(/%2C/gi, ",");
    return this.pairs.map(([k, v]) => `${encode(k)}=${encode(v)}`).join("&");
  }
}

export function routeHref(route: Route): string {
  const q = new Query();
  switch (route.view) {
    case "home":
      return `${BASE}/${route.anchor ? `#${encodeURIComponent(route.anchor)}` : ""}`;
    case "map": {
      if (route.goal) q.set("g", route.goal);
      if (route.node) q.set("n", route.node);
      if (route.trace) q.set("t", route.trace);
      if (route.lens) q.set("lens", route.lens);
      if (route.edge) q.set("e", edgeParam(route.edge));
      if (route.lean) q.set("v", "lean");
      if (route.decl) q.set("d", route.decl);
      if (route.declModule) q.set("dm", route.declModule);
      const s = q.toString();
      return `${BASE}/map/${s ? `?${s}` : ""}`;
    }
    case "read": {
      const library = libraryHref(route, BASE);
      if (library) return library;
      if (route.at) q.set("l", route.at);
      if (route.node) q.set("n", route.node);
      if (route.lean) q.set("v", "lean");
      else if (route.graph) q.set("v", "graph");
      if (route.beside) q.set("beside", `${route.beside.stage}:${route.beside.anchor}`);
      if (route.decl) q.set("d", route.decl);
      if (route.declModule) q.set("dm", route.declModule);
      if (route.pdf) q.set("view", "pdf");
      if (route.pdf && route.page) q.set("page", String(route.page));
      const s = q.toString();
      return `${BASE}/read/${route.stage}/${s ? `?${s}` : ""}${route.anchor ? `#${encodeURIComponent(route.anchor)}` : ""}`;
    }
    case "checks":
      if (route.node) q.set("n", route.node);
      return `${BASE}/checks/${q.toString() ? `?${q}` : ""}`;
    case "compare": {
      if (route.node) q.set("n", route.node);
      if (route.at) q.set("at", route.at);
      if (route.levels) q.set("levels", route.levels.join(","));
      if (route.any) q.set("in", "any");
      const s = q.toString();
      return `${BASE}/compare/${s ? `?${s}` : ""}`;
    }
    case "lean": {
      if (route.module) q.set("m", route.module);
      if (route.decl) q.set("d", route.decl);
      if (route.file) q.set("file", route.file);
      if (route.folder) q.set("f", route.folder);
      if (route.index) q.set("list", route.index);
      const s = q.toString();
      return `${BASE}/lean/${s ? `?${s}` : ""}`;
    }
    case "about":
      return `${BASE}/about/${route.anchor ? `#${encodeURIComponent(route.anchor)}` : ""}`;
    case "search": {
      q.set("q", route.q);
      if (route.type) q.set("type", route.type);
      if (route.page && route.page > 1) q.set("p", String(route.page));
      return `${BASE}/search/?${q}`;
    }
    case "missing":
      return route.path;
  }
}

/**
 * The exact address the host serves. Each page is a directory there, so a path
 * without its slash is redirected, and a redirect loses `history.state`. Every
 * address the site writes has the slash, so a reload never redirects.
 */
export function canonicalPath(pathname: string): string {
  const path = pathname.replace(/\/+$/, "");
  if (path === BASE) return `${BASE}/`;
  const page = BASE && path.startsWith(`${BASE}/`) ? path.slice(BASE.length) : path;
  return /^\/(?:map|compare|lean|checks|about|search|read\/(?:long|short|expository))$/.test(page) ? `${path}/` : pathname;
}

// An address that reached us in another form (a server with no redirect, an old link).
if (canonicalPath(window.location.pathname) !== window.location.pathname) {
  const here = new URL(window.location.href);
  here.pathname = canonicalPath(here.pathname);
  replaceEntry(here);
}

let current = parseRoute(new URL(window.location.href));
const listeners = new Set<() => void>();

/**
 * Parse the address again, once tables it depends on have loaded. A library paper's phrase addresses
 * (/@<id>) name a phrase that may stand on a numbered result; until its table is read the first parse
 * can only treat it as a phrase alone, which would open no Lean.
 */
export function reparseCurrentRoute(): void {
  // A page that moved (a library paper's moved_pages) shows its new address once the table is read.
  const url = new URL(window.location.href);
  const inBase = BASE && url.pathname.startsWith(BASE) ? url.pathname.slice(BASE.length) : url.pathname;
  const moved = movedLibraryPath(inBase.replace(/\/+$/, "") || "/");
  const removedTo = moved === "/" || (!!moved && LIBRARY?.removed?.some((slug) => inBase.split("/").includes(slug)));
  if (moved && removedTo) {
    // A page no longer published: the paper's (or its edition's) own address. Only the pane's view
    // (v=lean or v=graph) is kept; no place of the old page is.
    const v = url.searchParams.get("v");
    url.pathname = moved === "/" ? `${BASE}/` : `${BASE}${moved}/`;
    url.search = v === "lean" || v === "graph" ? `?v=${v}` : "";
    url.hash = "";
    replaceEntry(url);
  } else if (moved) {
    url.pathname = `${BASE}${moved}${/\/(?:@|lean\/)/.test(moved) ? "" : "/"}`;
    replaceEntry(url);
  }
  current = parseRoute(new URL(window.location.href));
}

function emit() {
  current = parseRoute(new URL(window.location.href));
  listeners.forEach((l) => l());
}

window.addEventListener("popstate", () => {
  arrive();
  emit();
});

/**
 * Push when what the reader is looking at changes (page, pinned record, passage,
 * Lean declaration, search query). Replace for refinements (tabs, scroll, camera,
 * filters). Leave hooks run first, so every link keeps its place with no special
 * cases. Following and pointing never push.
 */
export function navigate(to: Route | string, options: { replace?: boolean } = {}): void {
  const href = typeof to === "string" ? to : routeHref(to);
  const next = new URL(href, window.location.href);
  next.pathname = canonicalPath(next.pathname);
  if (next.href === window.location.href) return;
  if (options.replace) replaceEntry(next);
  else pushEntry(next);
  emit();
}

/**
 * One step from a Lean name to another: one history entry with its own address.
 * A page that shows Lean in place (the map's sheet, the reader's Lean page) keeps
 * what it shows and gains `&d=name`, with `&dm=module` where a name is declared
 * twice; `/lean` goes to the declaration; any other page goes to `/lean`. The
 * host reads `route.decl`. Back returns to the name in `from`, with its scroll.
 */
export function walkEntry(walk: { name: string; module?: string; from?: string }): void {
  const url = new URL(window.location.href);
  const here = parseRoute(url);
  let to: string;
  if (here.view === "map" || here.view === "read") {
    url.searchParams.set("d", walk.name);
    if (walk.module) url.searchParams.set("dm", walk.module);
    else url.searchParams.delete("dm");
    // A selected step gives way to the declaration; a selected record stays behind it.
    if (here.view === "map") url.searchParams.delete("e");
    to = url.href;
  } else to = new URL(routeHref({ view: "lean", module: walk.module, decl: walk.name }), url).href;
  if (to === window.location.href) return;
  if (walk.from) leaveAs(walk.from.slice(walk.from.lastIndexOf(".") + 1));
  navigate(to);
}

/** What a page is called on the Back control when it has not named its place more exactly. */
export function placeOf(route: Route): string {
  switch (route.view) {
    case "home":
      return "the front page";
    case "map":
      return "the map";
    case "read":
      return route.decl?.split(".").pop() ?? ({ long: "the long record", short: "the short paper", expository: "the exposition" } as Record<string, string>)[route.stage] ?? "the paper";
    case "checks":
      return "What ran";
    case "compare":
      return "Compare";
    case "lean":
      return route.decl?.split(".").pop() ?? "the Lean index";
    case "about":
      return "About";
    case "search":
      return route.q ? `search for “${route.q}”` : "search";
    case "missing":
      return "the previous page";
  }
}

setDefaultLabel((href) => placeOf(parseRoute(new URL(href))));

export function useRoute(): Route {
  return useSyncExternalStore(
    (l) => {
      listeners.add(l);
      return () => listeners.delete(l);
    },
    () => current,
  );
}

/**
 * Whether a link opens one of this site's own views. On GitHub Pages the sister
 * sites share the origin, so a path outside the site's base belongs to another site;
 * a path naming a file (a PDF, a JSON observation) is a file, and the API is the API.
 * The browser opens all of those itself.
 */
export function isAppPath(url: URL, origin: string = window.location.origin): boolean {
  if (url.origin !== origin) return false;
  if (BASE && url.pathname !== BASE && !url.pathname.startsWith(`${BASE}/`)) return false;
  if (url.pathname.startsWith(`${BASE}/api/`)) return false;
  return !/\.[a-z0-9]+$/i.test(url.pathname);
}

/** Intercept same-origin anchor clicks so internal links route without reload. */
export function useLinkInterception(): void {
  useEffect(() => {
    const onClick = (event: MouseEvent) => {
      if (event.defaultPrevented || event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
      const anchor = (event.target as Element | null)?.closest?.("a");
      if (!anchor || anchor.target || anchor.hasAttribute("download") || anchor.dataset.external !== undefined) return;
      const href = anchor.getAttribute("href");
      if (!href || href.startsWith("#") || href.startsWith("mailto:")) return;
      const url = new URL(href, window.location.href);
      if (!isAppPath(url)) return;
      event.preventDefault();
      navigate(url.pathname + url.search + url.hash);
    };
    document.addEventListener("click", onClick);
    return () => document.removeEventListener("click", onClick);
  }, []);
}
